package souther.runtime;

import java.math.BigDecimal;
import java.util.Objects;

/**
 * Whether two Souther values are the same one, and the hash that agrees with it. This is the one
 * definition: a collection, a generated class and the generated bytecode all reach it rather than
 * writing the rule again.
 *
 * <p>Most values answer for themselves. A String, a Long, a Boolean, a LocalDate, a generated data
 * class — their own {@code equals} already is the language's equality, so this asks them. Two kinds
 * cannot. A {@code BigDecimal}'s {@code equals} calls 1.0 and 1.00 different, and the same amount
 * arrives with a different scale depending on whether it was read from JSON or from a DB column; the
 * rule that scale is not part of a Decimal's identity lives here. A container that implements a JDK
 * collection interface owes that interface its {@code equals} and {@code hashCode}, so it carries
 * the language's semantics on {@link ValueSemantics} and this asks for them there.
 *
 * <p>Equality ignoring scale forces the hash to ignore it too. A value that compares equal and
 * hashes differently lands in another bucket and stops being findable by its own key — Groovy
 * changed {@code ==} and left {@code hashCode} alone, and that bug is still open.
 *
 * <p>The {@code BigDecimal} overloads are what the generated bytecode calls where both operands are
 * statically a Decimal. They share the body with the general form, so there is one rule, not two.
 */
public final class Values {

    private Values() {}

    public static boolean equal(Object a, Object b) {
        if (a == b) {
            return true;
        }
        if (a == null || b == null) {
            return false;
        }
        if (answersForItself(a.getClass())) {
            return a.equals(b);
        }
        if (a instanceof BigDecimal x) {
            return b instanceof BigDecimal y && equal(x, y);
        }
        if (a instanceof ValueSemantics s) {
            return s.valueEquals(b);
        }
        if (b instanceof ValueSemantics s) {
            return s.valueEquals(a);
        }
        return a.equals(b);
    }

    /** Two amounts are the same amount when they differ only in scale. */
    public static boolean equal(BigDecimal a, BigDecimal b) {
        return a == null ? b == null : b != null && a.compareTo(b) == 0;
    }

    public static int hash(Object v) {
        if (v == null) {
            return 0;
        }
        if (answersForItself(v.getClass())) {
            return v.hashCode();
        }
        if (v instanceof BigDecimal d) {
            return hash(d);
        }
        if (v instanceof ValueSemantics s) {
            return s.valueHash();
        }
        return v.hashCode();
    }

    /**
     * Whether a carrier's own {@code equals} and {@code hashCode} are already what the language
     * means, decided by the exact class so the check is a load and a compare.
     *
     * <p>Almost every carrier qualifies, so this is a shortcut past the two tests below rather than a
     * list of what is allowed — these two are named because they are what a Map is keyed by and a
     * List holds in the walks that decide how the runtime performs, and a class check against a final
     * class costs a fraction of the interface check {@link ValueSemantics} needs.
     *
     * <p>A class listed here is one whose equality this class then never inspects, so a carrier whose
     * own equality is not the language's — {@code BigDecimal} is the one there is — MUST NOT be added.
     */
    static boolean answersForItself(Class<?> carrier) {
        return carrier == Long.class || carrier == String.class;
    }

    /** The hash of an amount, taken after dropping the scale its equality ignores. */
    public static int hash(BigDecimal v) {
        return v == null ? 0 : v.stripTrailingZeros().hashCode();
    }
}
